/**
 * render/regions.ts — the FROZEN contract between the lead's composition
 * (render/index.tsx) and the five lanes' region components.
 *
 * Written ONCE by the Wave 3 module lead (lane: lead). Lanes implement their
 * region against these props and do NOT edit this file — escalate needed
 * changes to the coordinator instead.
 *
 * Coordinate system: render/index.tsx places each region in its own
 * `<g transform="translate(MARGIN, bandY)">`; regions draw in LOCAL
 * coordinates starting at (0, 0) and stay inside the band height reserved
 * for them (the *BAND constants below — render/index.tsx uses the same
 * constants to stack the sections, so a region taller than its band overlaps
 * the next section).
 *
 * `highlights` is the FULL highlight list of the current step (PLAN.md §3.1);
 * each region filters it to the entity ids it draws and maps roles onto the
 * primitives' `role` prop.
 */

import type { Highlight } from "@core/engine-contract";
import type { CompactionStrategy, Job, MemTable, SSTable, WalSegment } from "../state";

/** Shared props every region receives. */
export interface RegionBaseProps {
  highlights: Highlight[];
  speed: number;
  reducedMotion: boolean;
}

/** WAL segments region. Lane: crash/bulk. */
export interface WalViewProps extends RegionBaseProps {
  wal: WalSegment[];
  /** Next sequence number — the active WAL segment's tail position. */
  seq: number;
}

/** MemTables region (active + immutable). Lane: crash/bulk. */
export interface MemTableViewProps extends RegionBaseProps {
  memtables: MemTable[];
}

/**
 * L0 + levels region — draws every SSTable. Lane: leveled.
 * Under stcs, `levels` is always [] and every file lives in `l0` as an
 * unordered sorted run; use `strategy` to pick the layout.
 */
export interface LevelsViewProps extends RegionBaseProps {
  l0: SSTable[];
  levels: SSTable[][];
  strategy: CompactionStrategy;
}

/**
 * Compaction merge-stream region. Lane: STCS.
 * Draws the animated merge-sort: jobs' `output` streams and the l0 files
 * they consume. Flush jobs exist too — decide which jobs to render here.
 */
export interface MergeViewProps extends RegionBaseProps {
  jobs: Job[];
  l0: SSTable[];
  levels: SSTable[][];
}

/**
 * Bloom filter region. Lane: read.
 * Draws the probed files' bloom bit arrays (core primitive: BitArray) and
 * the hash → bit positions of the current read.
 */
export interface BloomViewProps extends RegionBaseProps {
  l0: SSTable[];
  levels: SSTable[][];
}

/**
 * One background job's row. Implemented FULLY by the lead (both compaction
 * lanes reuse it); lanes do NOT edit this file.
 */
export interface JobRowProps extends RegionBaseProps {
  job: Job;
  memtables: MemTable[];
  l0: SSTable[];
  levels: SSTable[][];
}

// --- Layout bands (px), shared by render/index.tsx and the regions ----------

/** Band height per WAL segment inside WalView. */
export const WAL_ROW_H = 26;

/** Band height per MemTable inside MemTableView. */
export const MEMTABLE_ROW_H = 46;

/** Band height of one JobRow. */
export const JOB_ROW_H = 44;

/** Fixed band for LevelsView (L0 + levels wrap inside it). */
export const LEVELS_BAND = 300;

/** Fixed band for MergeView (the STCS merge animation). */
export const MERGE_BAND = 96;

/** Fixed band for BloomView (the read lane's bloom strip). */
export const BLOOM_BAND = 76;
